<script>(function(){var t=document.getElementById('qtrack');if(!t)return;var dots=document.querySelectorAll('.q-dots i'),n=t.children.length,i=0;
function go(k){i=(k+n)%n;t.scrollTo({left:t.children[i].offsetLeft-t.offsetLeft,behavior:'smooth'});dots.forEach(function(d,j){d.className=j===i?'on':''})}
document.querySelectorAll('[data-q]').forEach(function(b){b.onclick=function(){go(i+Number(b.dataset.q)*(document.dir==='rtl'?1:1))}});
t.addEventListener('scroll',function(){var w=t.clientWidth||1,k=Math.round(Math.abs(t.scrollLeft)/w);if(k!==i){i=k;dots.forEach(function(d,j){d.className=j===i?'on':''})}},{passive:true});go(0)})();
(function(){var s=document.getElementById('g-service');if(!s)return;var T={none:{{.t.wait_none}},min:{{.t.wait_min}},hours:{{.t.wait_hours}}},W={none:{{.t.waiting_none}},one:{{.t.waiting_one}},many:{{.t.waiting_many}}},last=null;
function show(){if(!last)return;(last.services||[]).forEach(function(x){if(String(x.id)!==s.value)return;var n=x.w.length+(x.more||0);document.querySelector('.js-g-waiting').textContent=n===0?W.none:n===1?W.one:W.many.replace('{n}',n);document.querySelector('.js-g-wait').textContent=rxWait(n,x.m,x.d,T)})}
s.addEventListener('change',function(){if(last)show();else fetch('/api/queue').then(function(r){return r.json()}).then(function(d){last=d;show()})});
window.addEventListener('rxboard',function(e){last=e.detail;show()})})();
</script>
{{template "home_live" .}}{{template "bottom" .}}

templates.home_live:
{{template "live_js" .}}<script>
(function(){var T={none:{{.t.wait_none}},min:{{.t.wait_min}},hours:{{.t.wait_hours}}},W={none:{{.t.waiting_none}},one:{{.t.waiting_one}},many:{{.t.waiting_many}}},ar={{if eq .lang "ar"}}true{{else}}false{{end}},seen=0;
var boxes=document.querySelectorAll('#now-called,.js-now-called');
rxQueue({{.today}},function(d){try{window.dispatchEvent(new CustomEvent('rxboard',{detail:d}))}catch(x){}
(d.services||[]).forEach(function(s){var n=s.w.length+(s.more||0);document.querySelectorAll('[data-svc="'+s.id+'"]').forEach(function(card){var a=card.querySelector('.js-waiting'),b=card.querySelector('.js-wait');
if(a)a.textContent=n===0?W.none:n===1?W.one:W.many.replace('{n}',n);if(b)b.textContent=rxWait(n,s.m,s.d,T)})});
document.querySelectorAll('[data-live=waiting]').forEach(function(e){e.textContent=d.waiting});document.querySelectorAll('[data-live=seen]').forEach(function(e){e.textContent=d.seen});
boxes.forEach(function(box){var label=box.querySelector('.q-now-label'),none=box.dataset.none||'',cur=(d.calls||[]).filter(function(c){return c.s}).slice(0,3);
box.textContent='';if(label)box.appendChild(label);
if(!cur.length){var p=document.createElement('span');p.className='q-none';p.textContent={{.t.nobody_called}};box.appendChild(p)}
cur.forEach(function(c,i){var e=document.createElement('span');e.className='q-call'+(i===0&&c.at+c.c!==seen?' is-new':'');var b=document.createElement('b');b.textContent=c.c;var r=document.createElement('span');r.textContent=ar?c.ra:c.r;e.appendChild(b);e.appendChild(r);box.appendChild(e)});
});if(cur0(d))seen=cur0(d).at+cur0(d).c})
function cur0(d){return (d.calls||[]).filter(function(c){return c.s})[0]}})();
</script>

