{{template "live_js" $}}<script>
(function(){var T={none:{{$.t.wait_none}},min:{{$.t.wait_min}},hours:{{$.t.wait_hours}}},W={none:{{$.t.waiting_none}},one:{{$.t.waiting_one}},many:{{$.t.waiting_many}}},box=document.querySelector('.q-queue-now');
