templates.staff:
{{template "top" .}}<div class="wrap q-staff"><div class="q-staff-top"><div><h1>{{.t.staff_title}}</h1><p class="quiet">{{.hours}}</p></div>
<a class="btn line" href="/screen{{.qs}}" target="_blank" rel="noopener">{{.t.open_screen}}</a></div>
{{with .error}}<p class="alert" role="alert" style="margin-top:20px">{{.}}</p>{{end}}
<div id="staff-board">{{template "staff_board" .}}</div>
<p class="q-staff-links"><a href="/staff/report{{.qs}}">{{.t.report_title}}</a><a href="/kiosk{{.qs}}" target="_blank" rel="noopener">{{.t.kiosk_title}}</a></p></div>
{{template "live_js" .}}<script>
(function(){var box=document.getElementById('staff-board'),busy=false,again=false;
function load(){if(busy){again=true;return}busy=true;fetch('/staff?part=1&lang={{.lang}}',{cache:'no-store',credentials:'same-origin'}).then(function(r){return r.ok?r.text():''}).then(function(h){busy=false;
if(h&&!box.contains(document.activeElement)||h&&document.activeElement===document.body){var doc=new DOMParser().parseFromString(h,'text/html'),n=doc.getElementById('staff-board-in');if(n)box.replaceChildren(n)}if(again){again=false;load()}}).catch(function(){busy=false})}
rxQueue({{.today}},function(){load()});
box.addEventListener('submit',function(e){var f=e.target;if(!window.fetch||!f.matches('form[data-ajax]'))return;e.preventDefault();var b=f.querySelector('button');if(b)b.disabled=true;
var fd=new URLSearchParams(new FormData(f));fd.set('ajax','1');fetch(f.action,{method:'POST',body:fd,credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(j&&j.error)alert(j.error);if(b)b.blur();load()}).catch(function(){f.submit()})});})();
</script>{{template "bottom" .}}

