(function(){var el=document.getElementById('ticket'),code=el.dataset.code,sid=el.dataset.svc,k={{$.k}},lang={{$.lang}},T={none:{{$.t.wait_none}},min:{{$.t.wait_min}},hours:{{$.t.wait_hours}}},
A={none:{{$.t.ahead_none}},one:{{$.t.ahead_one}},many:{{$.t.ahead_many}}},live=document.querySelector('.js-live'),calls=Number(el.dataset.calls)||0,busy=false;
function line(n){var ol=document.querySelector('.js-line');if(!ol)return;ol.textContent='';var show=Math.min(n,8);for(var i=0;i<show;i++)ol.appendChild(document.createElement('li'));if(n>8){var m=document.createElement('li');m.className='more';m.textContent='+'+(n-8);ol.insertBefore(m,ol.firstChild)}var y=document.createElement('li');y.className='you';y.textContent=code;ol.appendChild(y)}
function set(cls,v){var e=document.querySelector(cls);if(e)e.textContent=v}
