if(was!=='called'||k2>calls){el.classList.remove('is-called');void el.offsetWidth;el.classList.add('is-called');if(navigator.vibrate)navigator.vibrate([300,120,300])}calls=k2}
function fetchState(){if(busy)return;busy=true;fetch('/ticket?json=1&k='+encodeURIComponent(k)+'&lang='+lang,{cache:'no-store'}).then(function(r){return r.json()}).then(function(v){busy=false;
