scripts.admin_change:
// on_admin_change: the owner or staff changed a row in the admin panel. A ticket set to called, done or no-show gets its
// times (a called one also a room, the first one that sees its service), the screens are updated and the patients now
// close to their turn are told. Changes to services, rooms and the settings reach the screens at once.
function handle(req) {
  const b = req.body, c = clinic(), now = dubaiNow().stamp;
  if (['tickets', 'services', 'rooms', 'clinic'].indexOf(b.table) < 0) return {text: 'nothing to do'};
  if (b.table === 'tickets' && b.row) {
    const r = b.row, was = b.before ? b.before.status : '';
    if (r.status === 'called' && was !== 'called') {
      let room = r.room_id;
      if (!room) {
        const s = db.query('SELECT * FROM services WHERE id = ?', r.service_id)[0];
        const fit = s ? rooms().filter(x => roomServes(x, s))[0] : null;
        room = fit ? fit.id : null;
      }
      if (room) finishRoomExcept(room, r.id, now);
      db.exec('UPDATE tickets SET called_at = ?, wait_minutes = ?, calls = 1, room_id = ? WHERE id = ?', now, minutesBetween(r.taken_at, now), room, r.id);
    } else if ((r.status === 'done' || r.status === 'no_show' || r.status === 'left') && was !== r.status) {
      db.exec('UPDATE tickets SET done_at = ? WHERE id = ?', now, r.id);
    }
  }
  alertNear(c, req.origin);
  publishBoard(c);
  return {text: 'queue updated'};
}
function finishRoomExcept(room, id, stamp) {
  db.exec("UPDATE tickets SET status = 'done', done_at = ? WHERE day = ? AND room_id = ? AND status = 'called' AND id != ?", stamp, dubaiNow().date, room, id);
}

scripts.home:
// GET /: the services with their queue now, what is being called, and the clinic's hours and address.
function handle(req) {
  const c = clinic(), lang = langOf(req), t = texts(lang), b = boardData(c), qs = lang === 'ar' ? '?lang=ar' : '';
  const list = services().map((s, i) => {
    const q = b.services.filter(x => x.id === s.id)[0] || {w: []}, n = q.w.length + (q.more || 0), w = estimate(n, s, c);
    return {id: s.id, prefix: s.prefix, icon: s.icon || 'stethoscope', name: pick(s, 'name', lang), detail: pick(s, 'detail', lang) || '', description: pick(s, 'description', lang) || '',
      image: s.image || '', waiting: n, waitingText: n === 0 ? t.waiting_none : n === 1 ? t.waiting_one : fill(t.waiting_many, {n: n}),
      wait: w, waitText: waitText(w, t), minutes: svcMinutes(s, c), idx: i + 1};
  });
  const calls = b.calls.filter(x => x.s === 1).slice(0, 3).map(x => ({code: x.c, room: lang === 'ar' ? x.ra : x.r}));
  const rs = rooms(), d = page(req, {services: list, calls: calls, board: b, roomsOpen: rs.length, roomsLabel: rs.length === 1 ? t.stat_room : t.stat_rooms,
    week: weekHours(c, t, lang, dubaiNow().date), faq: faqOf(c, t, lang), reviews: db.query('SELECT * FROM testimonials WHERE active = 1 ORDER BY coalesce(position, 0), id LIMIT 3').map(r => ({quote: pick(r, 'quote', lang), name: r.name, area: pick(r, 'area', lang) || '', initial: String(r.name || '?').slice(0, 1)})),
    fill: Math.min(3, Math.max(1, list.length)), notifyAhead: Number(c.notify_ahead) || 0,
    toldBy: Number(c.notify_ahead) > 0 ? (c.whatsapp_alerts ? t.told_whatsapp : t.told_email) : '',
    avgText: b.avg > 0 ? waitText(b.avg, t) : '', seenText: fill(t.seen_today, {n: b.seen})});
  d.stats = [{icon: 'users', n: b.waiting, label: b.waiting === 1 ? t.stat_waiting_one : t.stat_waiting, live: 'waiting'},
    {icon: 'smile', n: b.seen, label: t.stat_seen, live: 'seen'}, {icon: 'clock', n: b.avg > 0 ? b.avg + ' ' + t.min_short : t.wait_none, label: t.stat_avg_wait},
    {icon: 'heart', n: rs.length, label: d.roomsLabel}];
  d.accent = pick(c, 'tagline_accent', lang) || '';
  d.mobileUse = Number(c.notify_ahead) > 0 && c.whatsapp_alerts ? t.mobile_use_wa : t.mobile_use;
  d.trust = [{icon: 'calendar', text: t.trust_walk_in}, {icon: Number(c.notify_ahead) > 0 && c.whatsapp_alerts ? 'chat' : 'phone', text: Number(c.notify_ahead) > 0 && c.whatsapp_alerts ? t.trust_whatsapp : t.trust_live},
    {icon: 'clock', text: d.hours}];
  d.facts = [{icon: 'clock', label: t.fact_hours, value: d.hours, note: d.openNote},
    {icon: 'ticket', label: t.fact_walk_in, value: t.fact_walk_in_v, note: t.fact_walk_in_n},
    {icon: 'phone', label: t.fact_told, value: d.toldBy || t.fact_told_screen, note: d.notifyAhead > 0 ? fill(d.notifyAhead === 1 ? t.fact_told_n_one : t.fact_told_n, {n: d.notifyAhead}) : t.fact_told_screen_n},
    {icon: 'heart', label: t.fact_free, value: t.fact_free_v, note: t.fact_free_n}];
  return {template: 'home', data: d};
}
// Questions every patient asks, answered from the settings.
function faqOf(c, t, lang) {
  const out = [{q: t.faq_how_q, a: t.faq_how_a}, {q: t.faq_wait_q, a: fill(t.faq_wait_a, {m: Number(c.avg_minutes) > 0 ? c.avg_minutes : 10})}];
  if (Number(c.notify_ahead) > 0) out.push({q: t.faq_leave_q, a: fill(c.whatsapp_alerts ? t.faq_leave_a_wa : t.faq_leave_a_mail, {n: c.notify_ahead})});
  out.push({q: t.faq_miss_q, a: t.faq_miss_a});
  if (!allDay(c) || Number(c.last_ticket_minutes) > 0) out.push({q: t.faq_last_q, a: fill(t.faq_last_a, {last: lastTicket(c), closes: c.closes || ''})});
  return out;
}

