  const list = services().map(s => {
    const q = b.services.filter(x => x.id === s.id)[0] || {w: []}, n = q.w.length + (q.more || 0);
    return {id: s.id, prefix: s.prefix, name: pick(s, 'name', lang), detail: pick(s, 'detail', lang) || '', waiting: n,
      waitingText: n === 0 ? t.waiting_none : n === 1 ? t.waiting_one : fill(t.waiting_many, {n: n}), waitText: waitText(estimate(n, s, c), t)};
  });
  const tk = ticketByToken(req.query.k), done = tk && tk.day === dubaiNow().date ? ticketView(tk, c, t, lang) : null;
  return {template: 'kiosk', data: page(req, {mobileHint: Number(c.notify_ahead) > 0 && c.whatsapp_alerts ? t.mobile_hint : t.mobile_hint_plain, title: t.kiosk_title, services: list, done: done, k: done ? tk.token : '',
