scripts.leave:
// POST /ticket/leave: the patient gives up their place; the patients behind them move up.
function handle(req) {
  const tk = ticketByToken(req.form.k), amp = req.form.lang === 'ar' ? '&lang=ar' : '';
  if (!tk) return {redirect: '/' + (amp ? '?lang=ar' : '')};
  if (tk.status === 'waiting') {
    db.exec("UPDATE tickets SET status = 'left', done_at = ? WHERE id = ?", dubaiNow().stamp, tk.id);
    const c = clinic();
    alertNear(c, req.origin);
    publishBoard(c);
  }
  return {redirect: '/ticket?k=' + tk.token + amp};
}

