scripts.new_day:
// Job, every night at 00:05 UAE time: the numbers left from earlier days are closed (a patient still in a room counts as
// seen), each finished day's numbers go to daily_stats, contact details older than keep_contact_days are wiped, the
// screens get the empty queue and the owner gets yesterday's numbers.
function handle(req) {
  const c = clinic(), today = dubaiNow().date, now = dubaiNow().stamp;
  db.exec("UPDATE tickets SET status = 'done', done_at = coalesce(done_at, called_at) WHERE day < ? AND status = 'called'", today);
  const closed = db.exec("UPDATE tickets SET status = 'closed', done_at = ? WHERE day < ? AND status = 'waiting'", now, today).rowsAffected;
  let written = 0, yesterday = null;
  for (const d of db.query('SELECT DISTINCT day FROM tickets WHERE day < ? AND day >= ? AND day NOT IN (SELECT day FROM daily_stats) ORDER BY day', today, addDays(today, -30))) {
    const r = db.query("SELECT COUNT(*) AS taken, SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END) AS seen, SUM(CASE WHEN status = 'no_show' THEN 1 ELSE 0 END) AS no_shows, SUM(CASE WHEN status IN ('left', 'closed') THEN 1 ELSE 0 END) AS gone, AVG(CASE WHEN called_at IS NOT NULL AND called_at != '' THEN wait_minutes END) AS w, MAX(wait_minutes) AS mx FROM tickets WHERE day = ?", d.day)[0];
    const busy = db.query('SELECT substr(taken_at, 12, 2) AS h, COUNT(*) AS n FROM tickets WHERE day = ? GROUP BY h ORDER BY n DESC, h LIMIT 1', d.day)[0];
    const row = {day: d.day, taken: r.taken, seen: r.seen || 0, no_shows: r.no_shows || 0, left_queue: r.gone || 0, avg_wait: Math.round(r.w || 0), max_wait: r.mx || 0, busiest_hour: busy ? busy.h + ':00' : ''};
    db.exec('INSERT INTO daily_stats (day, taken, seen, no_shows, left_queue, avg_wait, max_wait, busiest_hour) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      row.day, row.taken, row.seen, row.no_shows, row.left_queue, row.avg_wait, row.max_wait, row.busiest_hour);
    written++;
    if (d.day === addDays(today, -1)) yesterday = row;
  }
  const keep = c.keep_contact_days === null || c.keep_contact_days === undefined || c.keep_contact_days === '' ? 30 : Math.max(0, Number(c.keep_contact_days) || 0);
  const wiped = db.exec("UPDATE tickets SET name = '', phone = '', email = '', token = '' WHERE day < ? AND (name != '' OR phone != '' OR coalesce(email, '') != '' OR coalesce(token, '') != '')", addDays(today, -keep)).rowsAffected;
  publishBoard(c);
  if (yesterday && yesterday.taken > 0) {
    const t = texts('en');
    notify.owner({subject: fill(t.owner_day_subject, {n: yesterday.taken, w: yesterday.avg_wait}),
      text: fill(t.owner_day_text, {day: longDate(yesterday.day, t), n: yesterday.taken, seen: yesterday.seen, ns: yesterday.no_shows, gone: yesterday.left_queue, w: yesterday.avg_wait, mx: yesterday.max_wait, h: yesterday.busiest_hour})});
  }
  return {text: 'new day ' + today + ': ' + closed + ' left waiting closed, ' + written + ' days summed up, ' + wiped + ' old contacts wiped'};
}

scripts.report:
// GET /staff/report: the last 14 days from the tickets: patients, seen, no-shows and the average wait.
function handle(req) {
  const lang = langOf(req), t = texts(lang);
  if (!isStaff(req.user)) return {template: 'staff_denied', data: page(req, {title: t.report_title, seo: {noindex: true}})};
  const today = dubaiNow().date, from = addDays(today, -13);
  const rows = db.query("SELECT day, COUNT(*) AS taken, SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END) AS seen, SUM(CASE WHEN status = 'no_show' THEN 1 ELSE 0 END) AS no_shows, AVG(CASE WHEN called_at IS NOT NULL AND called_at != '' THEN wait_minutes END) AS w, MAX(wait_minutes) AS mx FROM tickets WHERE day >= ? GROUP BY day ORDER BY day DESC", from);
  const top = Math.max(1, ...rows.map(r => r.taken));
  const days = rows.map(r => ({day: r.day, label: longDate(r.day, t), taken: r.taken, seen: r.seen || 0, noShows: r.no_shows || 0, avg: Math.round(r.w || 0), max: r.mx || 0,
    pct: Math.round(r.taken * 100 / top), today: r.day === today}));
  const total = rows.reduce((a, r) => a + r.taken, 0), waited = rows.filter(r => r.w !== null);
  const avg = waited.length ? Math.round(waited.reduce((a, r) => a + r.w * r.taken, 0) / Math.max(1, waited.reduce((a, r) => a + r.taken, 0))) : 0;
  const per = db.query("SELECT s.name, s.name_ar, COUNT(t.id) AS n, AVG(CASE WHEN t.called_at IS NOT NULL AND t.called_at != '' THEN t.wait_minutes END) AS w FROM tickets t JOIN services s ON s.id = t.service_id WHERE t.day >= ? GROUP BY s.id ORDER BY n DESC", from)
    .map(r => ({name: pick(r, 'name', lang), n: r.n, avg: Math.round(r.w || 0)}));
  return {template: 'report', data: page(req, {title: t.report_title, days: days, total: total, avg: avg, perDay: days.length ? Math.round(total / days.length) : 0, per: per, seo: {noindex: true}})};
}

