scripts.staff:
// GET /staff: the staff page (signed-in visitors listed in the staff table): each room with its patient and the buttons
// to call the next one, finish or mark a no-show, and every service's waiting list. ?part=1 returns only the board, which
// the page swaps in when the queue moves.
function handle(req) {
  const lang = langOf(req), t = texts(lang);
  if (!isStaff(req.user)) return {template: 'staff_denied', data: page(req, {title: t.staff_title, seo: {noindex: true}})};
  const c = clinic(), day = dubaiNow().date, svc = {};
  for (const s of services()) svc[s.id] = s;
  const rs = rooms().map(r => {
    const cur = db.query("SELECT * FROM tickets WHERE day = ? AND room_id = ? AND status = 'called' ORDER BY called_at DESC LIMIT 1", day, r.id)[0];
    const serves = Object.keys(svc).map(k => svc[k]).filter(s => roomServes(r, s)).map(s => s.prefix).join(' ');
    return {id: r.id, name: pick(r, 'name', lang), who: pick(r, 'who', lang) || '', serves: serves,
      cur: cur ? {id: cur.id, code: cur.code, name: cur.name, service: svc[cur.service_id] ? pick(svc[cur.service_id], 'name', lang) : '', at: String(cur.called_at).slice(11, 16), calls: cur.calls || 1} : null};
  });
  const lists = Object.keys(svc).map(k => svc[k]).map(s => ({id: s.id, name: pick(s, 'name', lang), prefix: s.prefix,
    rows: db.query("SELECT id, code, name, phone, substr(taken_at, 12, 5) AS at, alerted, source FROM tickets WHERE day = ? AND service_id = ? AND status = 'waiting' ORDER BY id LIMIT 60", day, s.id)
      .map((x, i) => ({id: x.id, code: x.code, name: x.name, phone: x.phone, at: x.at, told: x.alerted && x.alerted !== 'near' && x.alerted !== 'failed', reception: x.source === 'reception',
        waitText: waitText(estimate(i, s, c), t)}))}));
  const recent = db.query("SELECT id, code, name, status, substr(coalesce(done_at, called_at, taken_at), 12, 5) AS at FROM tickets WHERE day = ? AND status IN ('done', 'no_show', 'left') ORDER BY coalesce(done_at, called_at) DESC, id DESC LIMIT 8", day)
    .map(x => ({id: x.id, code: x.code, name: x.name, at: x.at, status: x.status, statusText: t['status_' + x.status], noShow: x.status === 'no_show'}));
  const b = boardData(c);
  const d = page(req, {title: t.staff_title, rooms: rs, lists: lists, recent: recent, board: b, avgText: b.avg > 0 ? waitText(b.avg, t) : t.wait_none, seo: {noindex: true}});
  return {template: req.query.part === '1' ? 'staff_board' : 'staff', data: d};
}

scripts.staff_act:
// POST /staff/act: action next (finish the room's patient and call the next one), call (a chosen ticket), done, no_show,
// recall (call again) or back (a no-show returns to the queue).
function handle(req) {
  const amp = req.form.lang === 'ar' ? '?lang=ar' : '';
  if (!isStaff(req.user)) return {status: 403, text: 'Not on the staff list'};
  const out = staffAction(clinic(), String(req.form.action || ''), req.form.room, req.form.ticket, req.origin);
  if (req.form.ajax === '1') return out.error ? {status: 400, json: {error: texts(langOf(req))[out.error] || out.error}} : {json: {ok: true, code: out.ticket ? out.ticket.code : ''}};
  return {redirect: '/staff' + amp + (out.error ? (amp ? '&' : '?') + 'error=' + out.error : '') + '#room-' + (Number(req.form.room) || 0)};
}

scripts.take:
// POST /take: a new number for the service. No sign-in: name and mobile are enough. One active number per mobile a day.
function handle(req) {
  const f = req.form, lang = f.lang === 'ar' ? 'ar' : 'en', amp = lang === 'ar' ? '&lang=ar' : '', kiosk = f.kiosk === '1';
  const s = serviceById(f.service), c = clinic(), now = dubaiNow();
  const back = (err) => {
    if (kiosk) return {redirect: '/kiosk?error=' + err + amp};
    const q = '&name=' + encodeURIComponent(String(f.name || '').slice(0, 80)) + '&phone=' + encodeURIComponent(String(f.phone || '').slice(0, 30)) + '&email=' + encodeURIComponent(String(f.email || '').slice(0, 120));
    return {redirect: (s ? '/s/' + s.id : '/') + '?error=' + err + amp + q};
  };
  if (!s) return back('error_service');
  const name = String(f.name || '').replace(/\s+/g, ' ').trim().slice(0, 80), phone = cleanPhone(f.phone);
  let mail = String(f.email || '').trim().toLowerCase().slice(0, 120);
  if (!name) return back('error_name');
  if (!phone) return back('error_phone');
  if (mail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mail)) return back('error_email');
  const st = openState(c, now);
  if (!st.open) return back('error_' + st.why);
  const dup = db.query("SELECT token FROM tickets WHERE day = ? AND phone = ? AND status IN ('waiting', 'called') LIMIT 1", now.date, phone)[0];
  if (dup) return back('error_already');
  const tk = newTicket(c, s, {name: name, phone: phone, email: mail, lang: lang, source: kiosk ? 'reception' : 'phone'}, now);
  publishBoard(c);
  return {redirect: (kiosk ? '/kiosk?k=' : '/ticket?k=') + tk.token + amp};
}

scripts.ticket:
// GET /ticket?k=<the ticket's secret>: the patient's own ticket, its place in the queue and the estimate, live.
// With json=1 the same as JSON, for the page when the queue moves. Without k: where to find a ticket.
function handle(req) {
  const tk = ticketByToken(req.query.k), lang = langOf(req), t = texts(lang);
  if (req.query.json === '1') {
    if (!tk) return {status: 404, json: {error: 'not found'}};
    const v = ticketView(tk, clinic(), t, lang);
    delete v.name;
    return {json: v};
  }
  if (!req.query.k) return {template: 'not_found', data: page(req, {title: t.my_ticket, findTicket: true, seo: {noindex: true}})};
  if (!tk) return {status: 404, template: 'not_found', data: page(req, {title: t.ticket_missing_title, missing: true, seo: {noindex: true}})};
  const c = clinic(), v = ticketView(tk, c, t, lang);
  return {template: 'ticket', data: page(req, {title: fill(t.ticket_title, {code: tk.code}), tk: v, k: tk.token, ticketNote: pick(c, 'ticket_note', lang) || '',
    seo: {noindex: true}})};
}

lib.common:
function langOf(req) { return req.query.lang === 'ar' || (req.form && req.form.lang === 'ar') ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function clinic() { return db.query('SELECT * FROM clinic ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n || 0).toFixed(2); }
// An amount with its currency in the page's language, from texts.money: "AED 250.00" or "250.00 د.إ". The queue takes no
// payments, so nothing calls it; it stays for an owner who adds a paid service.
function price(n, t) { return (t.money || 'AED {n}').replace('{n}', money(n)); }
function amount(n, t) { const v = round2(n || 0); return (t.money || 'AED {n}').replace('{n}', v % 1 === 0 ? String(v) : v.toFixed(2)).replace(/ /g, ' '); }
// 'YYYY-MM-DD' as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// The Arabic value of a column pair such as name / name_ar, or the English one when there is none.
function pick(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }
// A text with {placeholders} filled in.
function fill(s, vals) { s = String(s || ''); for (const k in vals) s = s.split('{' + k + '}').join(String(vals[k])); return s; }
// The current address in the other language, keeping the other query parameters (k, error).
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
function page(req, extra) {
  const lang = langOf(req), c = clinic(), t = texts(lang), err = String(req.query.error || '');
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const now = dubaiNow(), st = openState(c, now);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: t, user: req.user,
    biz: c, theme: theme(c), bizName: pick(c, 'name', lang), tagline: pick(c, 'tagline', lang), story: pick(c, 'story', lang) || '',
    intro: pick(c, 'intro', lang) || '', label: pick(c, 'label', lang) || '', address: pick(c, 'address', lang) || '', path: req.path, qs: qs, amp: lang === 'ar' ? '&lang=ar' : '',
    here: req.path + qs, langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'), wa: (c.whatsapp || '').replace(/[^0-9]/g, ''),
    tel: (c.phone || '').replace(/[^0-9+]/g, ''), today: now.date, open: st.open, openNote: openNote(c, st, t),
    hours: hoursToday(c, now.date, t), error: err.indexOf('error_') === 0 && t[err] ? t[err] : ''};
  if (base.theme.boutique) base.hourLines = hourLines(c, t);
  for (const k in extra) base[k] = extra[k];
  base.seo = seoOf(req, base, c, 'MedicalClinic', base.seo);
  return base;
}

// Dates and times are UAE local time (UTC+4 all year, no daylight saving), kept as text: 'YYYY-MM-DD', 'HH:MM' and
// 'YYYY-MM-DD HH:MM:SS' for the moments a ticket was taken, called and finished.
const DAYS = {en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
  ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
function dubaiNow() { const s = new Date(Date.now() + 4 * 3600 * 1000).toISOString(); return {date: s.slice(0, 10), time: s.slice(11, 16), stamp: s.slice(0, 10) + ' ' + s.slice(11, 19)}; }
function addDays(date, n) { const p = date.split('-'); return new Date(Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]) + n)).toISOString().slice(0, 10); }
function weekday(date) { const p = date.split('-'); return new Date(Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]))).getUTCDay(); }
function mins(t) { const p = String(t || '').split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); }
// Minutes between two 'YYYY-MM-DD HH:MM:SS' stamps.
function minutesBetween(a, b) {
  const x = Date.parse(String(a || '').replace(' ', 'T') + 'Z'), y = Date.parse(String(b || '').replace(' ', 'T') + 'Z');
  return isNaN(x) || isNaN(y) ? 0 : Math.max(0, Math.round((y - x) / 60000));
}
function validTime(s) { return /^([01]?\d|2[0-3]):[0-5]\d$/.test(String(s || '').trim()); }
function closedDays(c) { return String(c.closed_days || '').split(',').map(x => x.trim()).filter(x => x !== '').map(Number); }
// Whether numbers can be taken now: open today, between the opening time and the last number, under the daily limit.
function openState(c, now) {
  const opens = validTime(c.opens) ? mins(c.opens) : 0, closes = validTime(c.closes) ? mins(c.closes) : 24 * 60;
  const last = closes - Math.max(0, Number(c.last_ticket_minutes) || 0), m = mins(now.time);
  if (closedDays(c).indexOf(weekday(now.date)) >= 0) return {open: false, why: 'closed_today'};
  if (m < opens) return {open: false, why: 'not_yet'};
  if (m >= last) return {open: false, why: 'done_today'};
  if (Number(c.daily_limit) > 0) {
    const n = db.query('SELECT COUNT(*) AS n FROM tickets WHERE day = ?', now.date)[0].n;
    if (n >= Number(c.daily_limit)) return {open: false, why: 'full_today'};
  }
  return {open: true, why: ''};
}
// Open around the clock: from 00:00 to 24:00 (or 23:59) with no closed days.
function allDay(c) { return String(c.opens || '').trim().replace(/^0(?=0:)/, '') === '0:00' && /^(24:00|23:59)$/.test(String(c.closes || '').trim()); }
function openNote(c, st, t) {
  if (st.open && allDay(c) && !(Number(c.last_ticket_minutes) > 0)) return t.open_now_24;
  if (st.open) return fill(t.open_now, {closes: lastTicket(c)});
  return fill(t['shut_' + st.why] || '', {opens: c.opens || '', closes: c.closes || ''});
}
// The time of the last number: closing time minus last_ticket_minutes.
function lastTicket(c) {
  const closes = validTime(c.closes) ? mins(c.closes) : 24 * 60, m = Math.max(0, closes - Math.max(0, Number(c.last_ticket_minutes) || 0));
  const h = Math.floor(m / 60) % 24, r = m % 60;
  return (h < 10 ? '0' : '') + h + ':' + (r < 10 ? '0' : '') + r;
}
function hoursToday(c, date, t) {
  if (closedDays(c).indexOf(weekday(date)) >= 0) return t.closed_today;
  if (allDay(c)) return t.open_24;
  return fill(t.open_today, {opens: c.opens || '', closes: c.closes || ''});
}
// The opening hours in short lines ("Every day 08:00 – 21:00", or runs of days such as "Sat – Thu" and the closed days).
function hourLines(c, t) {
  const closed = closedDays(c), range = allDay(c) ? t.hours_24 : (c.opens || '') + ' – ' + (c.closes || ''), w = String(t.days_short || '').split('|'), runs = [];
  if (!closed.length || w.length !== 7) return [{days: t.every_day, hours: range, ltr: !allDay(c)}];
  for (let i = 0; i < 7; i++) {
    const shut = closed.indexOf(i) >= 0, last = runs[runs.length - 1];
    if (last && last.closed === shut) last.to = i; else runs.push({from: i, to: i, closed: shut});
  }
  return runs.map(r => ({days: r.from === r.to ? w[r.from] : w[r.from] + ' – ' + w[r.to], hours: range, closed: r.closed, ltr: !allDay(c)}));
}
// The week from Sunday, for the opening hours table; today is marked.
function weekHours(c, t, lang, today) {
  const closed = closedDays(c), names = DAYS[lang === 'ar' ? 'ar' : 'en'], wd = weekday(today), out = [];
  for (let i = 0; i < 7; i++) out.push({day: names[i], closed: closed.indexOf(i) >= 0, hours: allDay(c) ? t.hours_24 : (c.opens || '') + ' – ' + (c.closes || ''), today: i === wd, ltr: !allDay(c)});
  return out;
}

// What search engines, link previews (WhatsApp, Instagram) and AI assistants read in <head>: the page's
// description and picture, and schema.org data. The home page describes the clinic (kind is its schema.org type).
// The platform adds the canonical address, the other Open Graph tags and the hreflang links itself.
function seoOf(req, d, s, kind, item) {
  const abs = u => !u ? '' : /^https?:\/\//.test(u) ? u : req.origin + u;
  const short = x => { x = String(x || '').replace(/\s+/g, ' ').trim(); return x.length > 160 ? x.slice(0, 159) + '…' : x; };
  const here = req.origin + req.path + (d.lang === 'ar' ? '?lang=ar' : ''), name = pick(s, 'name', d.lang) || '';
  const out = {description: short(d.tagline || d.story), image: abs(s.hero_image || s.logo), icon: abs(s.logo)};
  const put = (o, k, v) => { if (v) o[k] = v; };
  if (item && item.name) {
    out.description = short(item.description) || out.description;
    out.image = abs(item.image) || out.image;
    const j = {'@context': 'https://schema.org', '@type': item.type || 'Service', name: item.name, url: here, provider: {'@type': kind, name: name}};
    put(j, 'description', short(item.description));
    put(j, 'image', abs(item.image));
    out.jsonld = j;
  } else if (item && item.noindex) {
    out.noindex = true;
  } else if (req.path === '/') {
    const j = {'@context': 'https://schema.org', '@type': kind, name: name, url: here};
    put(j, 'description', out.description);
    put(j, 'image', out.image);
    put(j, 'logo', out.icon);
    put(j, 'telephone', s.phone || s.whatsapp);
    put(j, 'address', d.address);
    if (validTime(s.opens) && validTime(s.closes)) {
      const closed = closedDays(s), days = DAYS.en.filter((x, i) => closed.indexOf(i) < 0);
      j.openingHoursSpecification = {'@type': 'OpeningHoursSpecification', dayOfWeek: days, opens: s.opens, closes: s.closes};
    }
    out.jsonld = j;
  }
  return out;
}

lib.queue:
// The queue. Every ticket belongs to one day (tickets.day, UAE date), so the queue starts empty each morning by itself;
// the daily job closes what was left and writes the day's numbers to daily_stats. Statuses: waiting, called (sent to a
// room), done, no_show, left (the patient left the queue) and closed (still waiting when the day ended).
// Everyone watches one public channel, public:queue: it carries ticket codes, rooms and counts, never a name or a number.
const QUEUE_CHANNEL = 'public:queue';
const ACTIVE = ['waiting', 'called'];

function services() { return db.query('SELECT * FROM services WHERE active = 1 ORDER BY coalesce(position, 0), id'); }
function serviceById(id) { return db.query('SELECT * FROM services WHERE id = ? AND active = 1', Number(id) || 0)[0]; }
function rooms() { return db.query('SELECT * FROM rooms WHERE active = 1 ORDER BY id'); }
// Minutes one patient takes for a service: its own minutes, else the clinic's average.
function svcMinutes(s, c) { return Number(s.minutes) > 0 ? Number(s.minutes) : Number(c.avg_minutes) > 0 ? Number(c.avg_minutes) : 10; }
// How many patients of a service are seen at the same time (doctors or rooms).
function svcDesks(s) { return Number(s.desks) > 0 ? Number(s.desks) : 1; }
// The estimated wait in minutes with this many patients ahead.
function estimate(ahead, s, c) { return ahead > 0 ? Math.ceil(ahead * svcMinutes(s, c) / svcDesks(s)) : 0; }
function waitText(m, t) { return m <= 0 ? t.wait_none : m < 60 ? fill(t.wait_min, {n: m}) : fill(t.wait_hours, {h: Math.floor(m / 60), m: m % 60}); }
// The services a room calls: the letters in rooms.services ("A, B"), or every service when it is empty.
function roomServes(room, s) {
  const list = String(room.services || '').toUpperCase().split(/[\s,]+/).filter(x => x);
  return !list.length || list.indexOf(String(s.prefix || '').toUpperCase()) >= 0;
}
function waitingCodes(day, sid) { return db.query("SELECT id, code FROM tickets WHERE day = ? AND service_id = ? AND status = 'waiting' ORDER BY id LIMIT 200", day, sid); }
function aheadOf(tk) {
  if (tk.status !== 'waiting') return 0;
  return db.query("SELECT COUNT(*) AS n FROM tickets WHERE day = ? AND service_id = ? AND status = 'waiting' AND id < ?", tk.day, tk.service_id, tk.id)[0].n;
}
function roomName(id, lang) { const r = db.query('SELECT name, name_ar FROM rooms WHERE id = ?', Number(id) || 0)[0]; return r ? pick(r, 'name', lang) : ''; }

// The state every screen shows, as small as possible: the latest calls, each service's waiting codes, today's counts.
function boardData(c) {
  const day = dubaiNow().date, svcs = [], roomNames = {};
  for (const r of db.query('SELECT id, name, name_ar FROM rooms')) roomNames[r.id] = r;
  let waiting = 0;
  for (const s of services()) {
    const w = waitingCodes(day, s.id).map(x => x.code);
    waiting += w.length;
    svcs.push({id: s.id, p: s.prefix, n: s.name, na: s.name_ar || s.name, m: svcMinutes(s, c), d: svcDesks(s), w: w.slice(0, 120), more: Math.max(0, w.length - 120)});
  }
  const calls = db.query("SELECT code, room_id, status, calls, service_id, substr(called_at, 12, 5) AS at FROM tickets WHERE day = ? AND called_at IS NOT NULL AND called_at != '' AND status IN ('called', 'done') ORDER BY called_at DESC, id DESC LIMIT 8", day)
    .map(x => { const r = roomNames[x.room_id] || {}; return {c: x.code, r: r.name || '', ra: r.name_ar || r.name || '', s: x.status === 'called' ? 1 : 0, k: x.calls || 1, at: x.at, sv: x.service_id}; });
  const st = db.query("SELECT COUNT(*) AS taken, SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END) AS seen, AVG(CASE WHEN called_at IS NOT NULL AND called_at != '' THEN wait_minutes END) AS w FROM tickets WHERE day = ?", day)[0];
  return {day: day, at: dubaiNow().time, calls: calls, services: svcs, waiting: waiting, seen: st.seen || 0, taken: st.taken || 0, avg: Math.round(st.w || 0)};
}
function publishBoard(c) {
  try { realtime.publish({channel: QUEUE_CHANNEL, data: boardData(c || clinic())}); } catch (e) { console.warn('queue board not sent: ' + (e.message || e)); }
}

// Patients whose turn is close are told once, by WhatsApp (when the clinic turned it on) and by email when they gave one.
// A patient who joined with that few ahead already sees it on the screen, so take() marks them 'near' and nobody is
// messaged twice. clinic.notify_ahead = 0 turns the messages off.
function alertNear(c, origin) {
  const n = Number(c.notify_ahead) || 0, day = dubaiNow().date;
  if (n <= 0) return 0;
  let sent = 0;
  for (const s of services()) {
    const w = db.query("SELECT * FROM tickets WHERE day = ? AND service_id = ? AND status = 'waiting' ORDER BY id LIMIT ?", day, s.id, n + 1);
    w.forEach((tk, i) => { if (!tk.alerted) { tellPatient(c, s, tk, i, origin); sent++; } });
  }
  return sent;
}
function tellPatient(c, s, tk, ahead, origin) {
  const lang = tk.lang === 'ar' ? 'ar' : 'en', t = texts(lang), name = pick(c, 'name', lang);
  const key = ahead <= 0 ? 'msg_next' : ahead === 1 ? 'msg_one' : 'msg_near';
  const text = fill(t[key], {n: ahead, code: tk.code, wait: waitText(estimate(ahead, s, c), t), clinic: name});
  const link = origin && tk.token ? origin + '/ticket?k=' + tk.token + (lang === 'ar' ? '&lang=ar' : '') : '';
  const via = [];
  if (c.whatsapp_alerts && tk.phone) {
    const wa = link && (text + ' ' + link).length <= 200 ? text + ' ' + link : text;
    try { whatsapp.send({to: tk.phone, text: wa}); via.push('whatsapp'); } catch (e) { console.warn('ticket ' + tk.code + ': WhatsApp not sent: ' + (e.message || e)); }
  }
  if (tk.email) {
    try { email.send({to: tk.email, subject: fill(t.mail_near_subject, {code: tk.code, clinic: name}), text: text + (link ? '\n\n' + t.mail_follow + '\n' + link : '') + '\n\n' + name + '\n'}); via.push('email'); }
    catch (e) { console.warn('ticket ' + tk.code + ': email not sent: ' + (e.message || e)); }
  }
  db.exec('UPDATE tickets SET alerted = ? WHERE id = ?', via.length ? via.join('+') : 'failed', tk.id);
}

// Staff actions; each returns the ticket it changed (or null) and publishes the new state.
function finishRoom(roomId, stamp) {
  db.exec("UPDATE tickets SET status = 'done', done_at = ? WHERE day = ? AND room_id = ? AND status = 'called'", stamp, dubaiNow().date, roomId);
}
function callTicket(tk, room, stamp) {
  db.exec("UPDATE tickets SET status = 'called', room_id = ?, called_at = ?, wait_minutes = ?, calls = 1 WHERE id = ? AND status = 'waiting'",
    room.id, stamp, minutesBetween(tk.taken_at, stamp), tk.id);
}
function staffAction(c, action, roomId, ticketId, origin) {
  const now = dubaiNow(), room = db.query('SELECT * FROM rooms WHERE id = ?', Number(roomId) || 0)[0];
  let tk = ticketId ? db.query('SELECT * FROM tickets WHERE id = ? AND day = ?', Number(ticketId) || 0, now.date)[0] : null;
  if (action === 'next' || action === 'call') {
    if (!room) return {error: 'error_room'};
    if (action === 'next') {
      const ids = services().filter(s => roomServes(room, s)).map(s => s.id);
      tk = ids.length ? db.query("SELECT * FROM tickets WHERE day = ? AND status = 'waiting' AND service_id IN (" + ids.map(() => '?').join(',') + ') ORDER BY id LIMIT 1', now.date, ...ids)[0] : null;
    }
    finishRoom(room.id, now.stamp);
    if (tk && tk.status === 'waiting') callTicket(tk, room, now.stamp); else tk = null;
  } else if (!tk) {
    return {error: 'error_ticket'};
  } else if (action === 'done' && tk.status === 'called') {
    db.exec("UPDATE tickets SET status = 'done', done_at = ? WHERE id = ?", now.stamp, tk.id);
  } else if (action === 'no_show' && ACTIVE.indexOf(tk.status) >= 0) {
    db.exec("UPDATE tickets SET status = 'no_show', done_at = ? WHERE id = ?", now.stamp, tk.id);
  } else if (action === 'recall' && tk.status === 'called') {
    db.exec('UPDATE tickets SET calls = coalesce(calls, 1) + 1, called_at = ? WHERE id = ?', now.stamp, tk.id);
  } else if (action === 'back' && tk.status === 'no_show') {
    db.exec("UPDATE tickets SET status = 'waiting', done_at = NULL WHERE id = ?", tk.id);
  } else {
    return {error: 'error_ticket'};
  }
  alertNear(c, origin);
  publishBoard(c);
  return {ticket: tk};
}

// A new ticket: the service's letter and the next number of the day (A001, A002...).
function newTicket(c, s, who, now) {
  const last = db.query('SELECT MAX(number) AS n FROM tickets WHERE day = ? AND service_id = ?', now.date, s.id)[0].n || 0;
  const number = last + 1, code = String(s.prefix || 'A').toUpperCase().slice(0, 2) + String(number).padStart(3, '0');
  const token = crypto.randomId();
  const r = db.exec('INSERT INTO tickets (day, number, code, service_id, name, phone, email, lang, status, source, token, taken_at, calls, alerted) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)',
    now.date, number, code, s.id, who.name, who.phone, who.email, who.lang, 'waiting', who.source, token, now.stamp, '');
  const tk = db.query('SELECT * FROM tickets WHERE id = ?', r.lastInsertId)[0];
  if (aheadOf(tk) <= (Number(c.notify_ahead) || 0)) db.exec("UPDATE tickets SET alerted = 'near' WHERE id = ?", tk.id);
  return tk;
}
// A mobile number as typed: digits with an optional +, and a UAE 05x number turned into +9715x.
function cleanPhone(raw) {
  let p = String(raw || '').replace(/[\s\-().]/g, '');
  if (/^00\d+$/.test(p)) p = '+' + p.slice(2);
  if (/^05\d{8}$/.test(p)) p = '+971' + p.slice(1);
  if (/^5\d{8}$/.test(p)) p = '+971' + p;
  return /^\+\d{8,15}$/.test(p) ? p : '';
}
function ticketByToken(k) {
  k = String(k || '');
  return k.length >= 16 ? db.query('SELECT * FROM tickets WHERE token = ?', k)[0] : null;
}
// What the patient's page shows, also as JSON for its live updates.
function ticketView(tk, c, t, lang) {
  const s = db.query('SELECT * FROM services WHERE id = ?', tk.service_id)[0] || {name: '', prefix: ''};
  const ahead = aheadOf(tk), today = tk.day === dubaiNow().date, status = tk.status === 'waiting' && !today ? 'closed' : tk.status;
  return {code: tk.code, status: status, statusText: t['status_' + status] || status, ahead: ahead, wait: estimate(ahead, s, c),
    waitText: waitText(estimate(ahead, s, c), t), aheadText: ahead === 0 ? t.ahead_none : ahead === 1 ? t.ahead_one : fill(t.ahead_many, {n: ahead}),
    room: roomName(tk.room_id, lang), service: pick(s, 'name', lang), serviceId: s.id, taken: String(tk.taken_at || '').slice(11, 16),
    called: String(tk.called_at || '').slice(11, 16), calls: tk.calls || 0, today: today, day: tk.day, dateText: longDate(tk.day, t), name: tk.name, minutes: svcMinutes(s, c), desks: svcDesks(s)};
}
// Staff are the visitor accounts whose email the owner listed in the staff table ("*" lets every signed-in visitor in,
// for trying the page out only).
function isStaff(user) {
  if (!user) return false;
  const e = String(user.email || '').toLowerCase();
  return db.query("SELECT COUNT(*) AS n FROM staff WHERE active = 1 AND (lower(trim(email)) = ? OR trim(email) = '*')", e || '-')[0].n > 0;
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   boutique (Gilda Display + DM Sans, Amiri + IBM Plex Sans Arabic; cream paper, terracotta accent, arches): style "standard"
//   with boutique true, so templates keep their layout and may add boutique sections; its look is the boutique template.
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier', 'boutique'];
const THEME_DEFAULT_WARM = '#b4643f';
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const boutique = font === 'boutique';
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : boutique ? THEME_DEFAULT_WARM : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, boutique: boutique, logo: row.logo || ''};
}
